```python
def transform(grid):
    H = len(grid)
    W = len(grid[0])
    if W == 0:
        return grid

    counts = {}
    for row in grid:
        for val in row:
            counts[val] = counts.get(val, 0) + 1
    bg_val = max(counts, key=counts.get)

    output_grid = []
    stripe_width = W // 3

    for r in range(H):
        marker_col = -1
        for c in range(W):
            if grid[r][c] != bg_val:
                marker_col = c
                break

        if marker_col != -1:
            stripe_idx = marker_col // stripe_width
            # FIXED mapping: stripe 0 → 2, stripe 1 → 4, stripe 2 → 3
            if stripe_idx == 0:
                out_val = 2
            elif stripe_idx == 1:
                out_val = 4
            else:
                out_val = 3
            output_grid.append([out_val] * W)
        else:
            output_grid.append(grid[r])

    return output_grid
